import java.util.*;

public class Ex03HashMapPutGet {
    static class Key {
        final int v;
        Key(int v) { this.v = v; }
        @Override public boolean equals(Object o) { return o instanceof Key k && k.v == v; }
        @Override public int hashCode() { return 1; }
    }
    public static void main(String[] args) {
        Map<Key, String> m = new HashMap<>();
        System.out.println("put(k1)= " + m.put(new Key(1), "a"));
        System.out.println("put(k2) old= " + m.put(new Key(2), "b"));
        System.out.println("size=" + m.size());
        System.out.println("get(k1)= " + m.get(new Key(1)));
        System.out.println("get(k2)= " + m.get(new Key(2)));
    }
}
